/* Original concept faucet built from volume meshes; no remote model dependency. */
(()=>{const canvas=document.getElementById('faucet3d'),slider=document.getElementById('hero-rotate'),out=document.getElementById('hero-angle');let gl;try{gl=canvas.getContext('webgl',{alpha:true,antialias:true,powerPreference:'low-power'})}catch(e){}if(!gl){canvas.hidden=true;document.querySelector('.product-fallback').hidden=false;document.querySelector('.hero-rotation').hidden=true;return}
const vert=`attribute vec3 aPosition;attribute vec3 aNormal;uniform mat4 uMVP;uniform mat4 uModel;varying vec3 vNormal;varying vec3 vWorld;void main(){vec4 w=uModel*vec4(aPosition,1.);vWorld=w.xyz;vNormal=mat3(uModel)*aNormal;gl_Position=uMVP*vec4(aPosition,1.);}`;
const frag=`precision mediump float;varying vec3 vNormal;varying vec3 vWorld;uniform vec3 uEye;float panel(float x,float center,float width){return 1.-smoothstep(width*.6,width,abs(x-center));}void main(){vec3 n=normalize(vNormal);vec3 view=normalize(uEye-vWorld);vec3 r=reflect(-view,n);float az=atan(r.x,r.z);float el=r.y;float env=.065+.08*(el*.5+.5);env+=.88*panel(az,-.95,.18)*smoothstep(-.6,.05,el);env+=.6*panel(az,1.15,.32);env+=.95*panel(az,2.65,.13);env+=.25*panel(el,.73,.28);env+=.3*panel(az,.08,.05);float rim=pow(1.-max(0.,dot(n,view)),3.);float diffuse=max(0.,dot(n,normalize(vec3(-2.,4.,3.))));float ao=mix(.63,1.,smoothstep(-1.5,.2,vWorld.y));vec3 c=vec3(env*.88+.05*diffuse+rim*.16)*ao;float spec=pow(max(0.,dot(reflect(-normalize(vec3(-2.,4.,3.)),n),view)),95.);c+=spec*.65;c=pow(c,vec3(.82));gl_FragColor=vec4(c,1.);}`;
function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('Product shader compilation failed');return s}let program;try{program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vert));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,frag));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Product shader link failed')}catch(e){canvas.hidden=true;document.querySelector('.product-fallback').hidden=false;document.querySelector('.hero-rotation').hidden=true;return}gl.useProgram(program);
const positions=[],normals=[];const norm=v=>{let l=Math.hypot(...v)||1;return v.map(x=>x/l)};const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
function tri(a,b,c,na,nb,nc){positions.push(...a,...b,...c);normals.push(...na,...nb,...nc)}
function lathe(profile,segments=80,offset=[0,0,0]){for(let j=0;j<profile.length-1;j++){let [ra,ya]=profile[j],[rb,yb]=profile[j+1];let dy=yb-ya,dr=rb-ra;for(let i=0;i<segments;i++){let a=i/segments*Math.PI*2,b=(i+1)/segments*Math.PI*2;const point=(r,y,t)=>[r*Math.cos(t)+offset[0],y+offset[1],r*Math.sin(t)+offset[2]];const normal=t=>norm([dy*Math.cos(t),-dr,dy*Math.sin(t)]);let p1=point(ra,ya,a),p2=point(ra,ya,b),p3=point(rb,yb,b),p4=point(rb,yb,a);tri(p1,p2,p3,normal(a),normal(b),normal(b));tri(p1,p3,p4,normal(a),normal(b),normal(a))}}}
function tube(path,ry,rz,segments=48){for(let j=0;j<path.length-1;j++){const a=path[j],b=path[j+1];const tangent=norm([b[0]-a[0],b[1]-a[1],b[2]-a[2]]);const side=norm(cross(tangent,[0,0,1])),depth=norm(cross(tangent,side));function point(p,t){return p.map((x,k)=>x+side[k]*Math.cos(t)*ry+depth[k]*Math.sin(t)*rz)}function normal(t){return norm(side.map((x,k)=>x*Math.cos(t)/ry+depth[k]*Math.sin(t)/rz))}for(let i=0;i<segments;i++){let t=i/segments*Math.PI*2,u=(i+1)/segments*Math.PI*2;tri(point(a,t),point(a,u),point(b,u),normal(t),normal(u),normal(u));tri(point(a,t),point(b,u),point(b,t),normal(t),normal(u),normal(t))}}// end caps
for(const [p,q,dir] of [[path[0],path[1],-1],[path[path.length-1],path[path.length-2],-1]]){const n=norm(p.map((x,k)=>(q[k]-x)*dir)),side=norm(cross(n,[0,0,1])),dep=norm(cross(n,side));for(let i=0;i<segments;i++){const point=t=>p.map((x,k)=>x+side[k]*Math.cos(t)*ry+dep[k]*Math.sin(t)*rz);tri(p,point(i/segments*Math.PI*2),point((i+1)/segments*Math.PI*2),n,n,n)}}}
// Base, seamless tall body, collar, head, and sculptural forward spout.
lathe([[0,-1.5],[.36,-1.5],[.39,-1.47],[.39,-1.42],[.36,-1.39],[.265,-1.39],[.25,-1.35],[.25,.63],[.245,.68],[0,.68]]);
lathe([[0,.69],[.247,.69],[.257,.72],[.257,.87],[.235,.9],[0,.9]]);
const path=[];for(let i=0;i<=24;i++){const t=i/24;path.push([.13+t*1.3,.54-.1*t-.09*t*t,0])}tube(path,.13,.23);
// Aerator beneath the tip.
lathe([[0,-.035],[.115,-.035],[.12,0],[.12,.025],[0,.025]],48,[1.33,.205,0]);
// Pivot and single slim lever.
lathe([[0,.9],[.11,.9],[.11,1.03],[0,1.03]],48);
tube([[-.07,1.015,0],[.12,1.06,0],[.45,1.115,0],[.78,1.15,0],[.98,1.16,0]],.035,.078,36);
const posBuf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,posBuf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(positions),gl.STATIC_DRAW);const pa=gl.getAttribLocation(program,'aPosition');gl.enableVertexAttribArray(pa);gl.vertexAttribPointer(pa,3,gl.FLOAT,false,0,0);const norBuf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,norBuf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(normals),gl.STATIC_DRAW);const na=gl.getAttribLocation(program,'aNormal');gl.enableVertexAttribArray(na);gl.vertexAttribPointer(na,3,gl.FLOAT,false,0,0);
const um=gl.getUniformLocation(program,'uModel'),up=gl.getUniformLocation(program,'uMVP'),ue=gl.getUniformLocation(program,'uEye');
function multiply(a,b){const o=new Float32Array(16);for(let c=0;c<4;c++)for(let r=0;r<4;r++)for(let k=0;k<4;k++)o[c*4+r]+=a[k*4+r]*b[c*4+k];return o}function perspective(fov,aspect,near,far){let f=1/Math.tan(fov/2),nf=1/(near-far);return new Float32Array([f/aspect,0,0,0,0,f,0,0,0,0,(far+near)*nf,-1,0,0,2*far*near*nf,0])}function lookAt(eye,target){const z=norm(eye.map((v,i)=>v-target[i])),x=norm(cross([0,1,0],z)),y=cross(z,x);return new Float32Array([x[0],y[0],z[0],0,x[1],y[1],z[1],0,x[2],y[2],z[2],0,-x.reduce((a,v,i)=>a+v*eye[i],0),-y.reduce((a,v,i)=>a+v*eye[i],0),-z.reduce((a,v,i)=>a+v*eye[i],0),1])}
let userAngle=0,scrollAngle=0,scale=1,renderQueued=false;const eye=[0,1.4,6.7];function draw(){renderQueued=false;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const ratio=Math.min(devicePixelRatio||1,2),width=Math.round(r.width*ratio),height=Math.round(r.height*ratio);if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height}gl.viewport(0,0,width,height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);const a=(-25+userAngle+scrollAngle)*Math.PI/180,c=Math.cos(a),s=Math.sin(a);const model=new Float32Array([c*scale,0,-s*scale,0,0,scale,0,0,s*scale,0,c*scale,0,-.15,-.02,0,1]);const pv=multiply(perspective(.64,width/height,.1,40),lookAt(eye,[.25,-.1,0]));gl.uniformMatrix4fv(um,false,model);gl.uniformMatrix4fv(up,false,multiply(pv,model));gl.uniform3fv(ue,eye);gl.drawArrays(gl.TRIANGLES,0,positions.length/3)}function requestDraw(){if(!renderQueued){renderQueued=true;requestAnimationFrame(draw)}}function setAngle(v){userAngle=Math.max(-180,Math.min(180,v));slider.value=String(Math.round(userAngle));out.value=Math.round(userAngle)+'°';requestDraw()}
slider.addEventListener('input',e=>setAngle(+e.target.value));document.getElementById('reset-hero').onclick=()=>setAngle(0);let pointer=null,lastX=0,lastY=0,dragging=false;canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointer=e.pointerId;lastX=e.clientX;lastY=e.clientY;dragging=false;canvas.setPointerCapture(pointer);canvas.classList.add('dragging')});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;if(!dragging&&Math.abs(dy)>Math.abs(dx)*1.6){return}if(Math.abs(dx)>1)dragging=true;if(dragging){setAngle(userAngle+dx*.55);lastX=e.clientX;lastY=e.clientY}});function release(){pointer=null;canvas.classList.remove('dragging')}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home'].includes(e.key)){e.preventDefault();setAngle(e.key==='Home'?0:userAngle+(e.key==='ArrowRight'?10:-10))}});new ResizeObserver(requestDraw).observe(canvas);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();canvas.hidden=true;document.querySelector('.product-fallback').hidden=false;document.querySelector('.hero-rotation').hidden=true});window.bathstoreProduct={setScroll(progress){scrollAngle=progress*125;scale=1+progress*.13;requestDraw()}};requestDraw();})();
